// ProcessActivityActivityID values for ProcessActivity.ActivityID (Activity ID).
const (
	// A request by the actor to launch another process. Refer to the launch_type_id attribute for
	// details of the specific launch type.
	ProcessActivityActivityIDLaunch = 1
	// A request by the actor to terminate a process. This activity is most commonly reflexive,
	// this being the case when a process exits at its own initiation. Note too that Windows
	// security products cannot always identify the actor in the case of inter-process termination.
	// In this case, actor.process and process refer to the exiting process, i.e. indistinguishable
	// from the reflexive case.
	ProcessActivityActivityIDTerminate = 2
	// A request by the actor to obtain a handle or descriptor to a process with the aim of
	// performing further actions upon that process. The target is usually a different process but
	// this activity can also be reflexive.
	ProcessActivityActivityIDOpen = 3
	// A request by the actor to execute code within the context of a process. The target is
	// usually a different process but this activity can also be reflexive. Refer to the
	// injection_type_id attribute for details of the specific injection type.
	ProcessActivityActivityIDInject = 4
	// A request by the actor to change its user identity by invoking the setuid() system call.
	// Common programs like su and sudo use this mechanism. Note that the impersonation mechanism
	// on Windows is not directly equivalent because it acts at the thread level.
	ProcessActivityActivityIDSetUserID = 5
)

